-- Для НОВОЙ пустой БД. Не миграция и не замена существующих таблиц.
-- Воссоздано по предоставленным колонкам и ограничениям.
-- Для id выбрана GENERATED BY DEFAULT AS IDENTITY: исходный запрос
-- не выгружал identity_generation, поэтому точный режим identity неизвестен.
BEGIN;

CREATE TABLE public.leads (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    chat_id BIGINT NOT NULL UNIQUE,
    username TEXT,
    first_name TEXT,
    status TEXT NOT NULL DEFAULT 'collecting'
        CHECK (status IN ('collecting', 'handoff_pending', 'handed_off', 'closed')),
    repair_type TEXT,
    area_sqm NUMERIC CHECK (area_sqm > 0),
    city TEXT,
    desired_timing TEXT,
    budget NUMERIC CHECK (budget >= 0),
    handoff_requested BOOLEAN NOT NULL DEFAULT false,
    unknown_fields TEXT[] NOT NULL DEFAULT '{}',
    last_question_field TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    client_name TEXT
);

CREATE TABLE public.messages (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    lead_id BIGINT NOT NULL REFERENCES public.leads(id),
    telegram_message_id BIGINT,
    direction TEXT NOT NULL CHECK (direction IN ('incoming', 'outgoing')),
    text TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    processing_status TEXT,
    last_alerted_at TIMESTAMPTZ,
    UNIQUE (lead_id, direction, telegram_message_id)
);

CREATE TABLE public.handoffs (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    lead_id BIGINT NOT NULL REFERENCES public.leads(id),
    manager_chat_id BIGINT NOT NULL,
    reason TEXT NOT NULL CHECK (reason IN ('data_collected', 'client_requested')),
    summary TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'pending'
        CHECK (status IN ('pending', 'sent', 'failed')),
    telegram_message_id BIGINT,
    last_error TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    sent_at TIMESTAMPTZ,
    last_alerted_at TIMESTAMPTZ,
    source_message_id BIGINT REFERENCES public.messages(id),
    client_confirmation_message_id BIGINT,
    UNIQUE (lead_id, manager_chat_id)
);

CREATE TABLE public.repair_knowledge (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    topic TEXT NOT NULL UNIQUE,
    content TEXT NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

COMMIT;
